    using System;

    // Fetch the rendered template text from pipeline environment variables
    string rowText = Environment.GetEnvironmentVariable("FormattedRow") ?? "";

    // Output directly to Console.Out (os.Stdout)
    Console.WriteLine(rowText);




    using System;
    using System.Collections.Generic;

    int loopIdx = int.TryParse(Environment.GetEnvironmentVariable("LOOP_INDEX"), out var li) ? li : 0;
    string header = $"\n========== Variables at LOOP_INDEX {loopIdx} ==========";
    Console.WriteLine(header);

    var pipelineVarNames = new[] {
        "DBPath", "DEPARTMENT", "FormattedRow", "ID", "LAST_OUTPUT", "LOOP_INDEX",
        "MinSalary", "NAME", "SALARY", "department", "id", "log_db_cs", "name", "salary"
    };

    var keys = new List<string>();
    foreach (var name in pipelineVarNames)
    {
        if (Environment.GetEnvironmentVariable(name) != null)
        {
            keys.Add(name);
        }
    }
    keys.Sort(StringComparer.Ordinal);

    foreach (var name in keys)
    {
        var val = Environment.GetEnvironmentVariable(name);
        Console.WriteLine($"  {name,-20} = {val}");
    }
    string footer = "=================================================";
    Console.WriteLine(footer);

flow.script:

using System;
using System.Collections.Generic;

string header = "\n========== Final Pipeline Variables ==========";
Console.WriteLine(header);

var pipelineVarNames = new[] {
    "DBPath", "DEPARTMENT", "FormattedRow", "ID", "LAST_OUTPUT", "LOOP_INDEX",
    "MinSalary", "NAME", "SALARY", "department", "id", "log_db_cs", "name", "salary"
};

var keys = new List<string>();
foreach (var name in pipelineVarNames)
{
    if (Environment.GetEnvironmentVariable(name) != null)
    {
        keys.Add(name);
    }
}
keys.Sort(StringComparer.Ordinal);

foreach (var name in keys)
{
    var val = Environment.GetEnvironmentVariable(name);
    Console.WriteLine($"  {name,-20} = {val}");
}
string footer = "==============================================";
Console.WriteLine(footer);
/* Environment.Exit(0); */
